cd /tmp && python3 - <<'EOF'
import json,re
s=open('/tmp/t1/empty.bimcraft').read()
s=re.sub(r'"uid": \d+', '"uid": 0', s)
d=json.loads(s)
def show(d, depth=0, maxdepth=2, prefix=''):
    if isinstance(d, dict):
        for k,v in d.items():
            sz=len(json.dumps(v))
            print('  '*depth + f'{k}: {type(v).__name__} ({sz})')
            if depth < maxdepth-1:
                show(v, depth+1, maxdepth)
    elif isinstance(d, list):
        print('  '*depth + f'[list of {len(d)}]')
show(d, 0, 2)
EOF

