/// Builds an object from pairs, keeping their order.
#[macro_export]
macro_rules! jobj {
    () => { $crate::json::Value::Obj($crate::json::Map::new()) };
    ($($k:expr => $v:expr),+ $(,)?) => {{
        let mut m = $crate::json::Map::new();
        $( m.insert($k, $crate::json::Value::from($v)); )+
        $crate::json::Value::Obj(m)
    }};
}

// ---------------------------------------------------------------- numbers

/// Shortest round-trip digits and the decimal exponent: value = 0.d1d2d3... * 10^kk
fn shortest_digits(x: f64) -> (String, i32) {
    // `{:e}` gives the shortest digits that round-trip, as ryu does.
    let s = format!("{:e}", x.abs());
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    // mant = d.ddd, so value = d.ddd * 10^exp = 0.dddd * 10^(exp+1)
    (digits, exp + 1)
}

/// Formats an f64 as serde_json (ryu) does.
pub fn fmt_f64(x: f64) -> String {
    if !x.is_finite() {
        return "null".to_string();
    }
    let mut out = String::new();
    if x.is_sign_negative() {
        out.push('-');
    }
    if x == 0.0 {
        out.push_str("0.0");
        return out;
    }
    let (digits, kk) = shortest_digits(x);
    let length = digits.len() as i32;
    let k = kk - length;
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in length..kk {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else if length == 1 {
        out.push_str(&digits);
        out.push('e');
        let _ = write!(out, "{}", kk - 1);
    } else {
        out.push_str(&digits[..1]);
        out.push('.');
        out.push_str(&digits[1..]);
        out.push('e');
        let _ = write!(out, "{}", kk - 1);
    }
    out
}

/// How serde's "invalid type" message shows a float (Rust's Display, with a `.0` for integers).
pub fn fmt_f64_display(x: f64) -> String {
    if x.is_finite() && x == x.trunc() && x.abs() < 1e16 {
        format!("{}.0", x as i64)
    } else {
        format!("{}", x)
    }
}

fn write_num(n: &Num, out: &mut String) {
    match n {
        Num::U(u) => {
            let _ = write!(out, "{}", u);
        }
        Num::I(i) => {
            let _ = write!(out, "{}", i);
        }
        Num::F(f) => out.push_str(&fmt_f64(*f)),
    }
}

pub fn write_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

pub fn write_compact(v: &Value, out: &mut String) {
    match v {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Num(n) => write_num(n, out),
        Value::Str(s) => write_str(s, out),
        Value::Arr(a) => {
            out.push('[');
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_compact(x, out);
            }
            out.push(']');
        }
        Value::Obj(m) => {
            out.push('{');
            for (i, (k, x)) in m.items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_str(k, out);
                out.push(':');
                write_compact(x, out);
            }
            out.push('}');
        }
    }
}

fn indent(out: &mut String, n: usize) {
    for _ in 0..n {
        out.push_str("  ");
    }
}

pub fn write_pretty(v: &Value, out: &mut String, level: usize) {
    match v {
        Value::Arr(a) => {
            if a.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push('[');
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                indent(out, level + 1);
                write_pretty(x, out, level + 1);
            }
            out.push('\n');
            indent(out, level);
            out.push(']');
        }
        Value::Obj(m) => {
            if m.items.is_empty() {
                out.push_str("{}");
                return;
            }
            out.push('{');
            for (i, (k, x)) in m.items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('\n');
                indent(out, level + 1);
                write_str(k, out);
                out.push_str(": ");
                write_pretty(x, out, level + 1);
            }
            out.push('\n');
            indent(out, level);
            out.push('}');
        }
        _ => write_compact(v, out),
    }
}

// ---------------------------------------------------------------- parsing

#[derive(Debug, Clone)]
pub struct ParseError {
    pub msg: String,
    pub line: usize,
    pub col: usize,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        if self.line == 0 {
            write!(f, "{}", self.msg)
        } else {
            write!(f, "{} at line {} column {}", self.msg, self.line, self.col)
        }
    }
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
    depth: usize,
}

impl<'a> Parser<'a> {
    /// Line and column of the byte before `self.i` (serde_json reports the last byte read).
    fn pos_at(&self, idx: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 0;
        for &b in &self.s[..idx.min(self.s.len())] {
            if b == b'\n' {
                line += 1;
                col = 0;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
    fn err(&self, msg: &str) -> ParseError {
        let (line, col) = self.pos_at(self.i);
        ParseError { msg: msg.to_string(), line, col }
    }
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn skip_ws(&mut self) {
        while let Some(b) = self.peek() {
            if b == b' ' || b == b'\n' || b == b'\t' || b == b'\r' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn parse_value(&mut self) -> Result<Value, ParseError> {
        self.skip_ws();
        let b = match self.peek() {
            None => return Err(self.err("EOF while parsing a value")),
            Some(b) => b,
        };
        match b {
            b'n' => {
                self.i += 1;
                self.ident(b"ull")?;
                Ok(Value::Null)
            }
            b't' => {
                self.i += 1;
                self.ident(b"rue")?;
                Ok(Value::Bool(true))
            }
            b'f' => {
                self.i += 1;
                self.ident(b"alse")?;
                Ok(Value::Bool(false))
            }
            b'-' | b'0'..=b'9' => self.parse_number(),
            b'"' => {
                self.i += 1;
                Ok(Value::Str(self.parse_string()?))
            }
            b'[' => {
                self.depth += 1;
                if self.depth > 128 {
                    self.i += 1;
                    return Err(self.err("recursion limit exceeded"));
                }
                self.i += 1;
                let mut items = Vec::new();
                self.skip_ws();
                if self.peek() == Some(b']') {
                    self.i += 1;
                    self.depth -= 1;
                    return Ok(Value::Arr(items));
                }
                loop {
                    let v = self.parse_value()?;
                    items.push(v);
                    self.skip_ws();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                            self.skip_ws();
                            if self.peek() == Some(b']') {
                                self.i += 1;
                                return Err(self.err("trailing comma"));
                            }
                        }
                        Some(b']') => {
                            self.i += 1;
                            break;
                        }
                        None => return Err(self.err("EOF while parsing a list")),
                        Some(_) => {
                            self.i += 1;
                            return Err(self.err("expected `,` or `]`"));
                        }
                    }
                }
                self.depth -= 1;
                Ok(Value::Arr(items))
            }
            b'{' => {
                self.depth += 1;
                if self.depth > 128 {
                    self.i += 1;
                    return Err(self.err("recursion limit exceeded"));
                }
                self.i += 1;
                let mut m = Map::new();
                self.skip_ws();
                if self.peek() == Some(b'}') {
                    self.i += 1;
                    self.depth -= 1;
                    return Ok(Value::Obj(m));
                }
                loop {
                    self.skip_ws();
                    match self.peek() {
                        Some(b'"') => {
                            self.i += 1;
                        }
                        None => return Err(self.err("EOF while parsing an object")),
                        Some(_) => {
                            self.i += 1;
                            return Err(self.err("key must be a string"));
                        }
                    }
                    let k = self.parse_string()?;
                    self.skip_ws();
                    match self.peek() {
                        Some(b':') => self.i += 1,
                        None => return Err(self.err("EOF while parsing an object")),
                        Some(_) => {
                            self.i += 1;
                            return Err(self.err("expected `:`"));
                        }
                    }
                    let v = self.parse_value()?;
                    // a duplicate key keeps the last value, in the first one's place
                    m.insert(&k, v);
                    self.skip_ws();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                            self.skip_ws();
                            if self.peek() == Some(b'}') {
                                self.i += 1;
                                return Err(self.err("trailing comma"));
                            }
                        }
                        Some(b'}') => {
                            self.i += 1;
                            break;
                        }
                        None => return Err(self.err("EOF while parsing an object")),
                        Some(_) => {
                            self.i += 1;
                            return Err(self.err("expected `,` or `}`"));
                        }
                    }
                }
                self.depth -= 1;
                Ok(Value::Obj(m))
            }
            _ => {
                self.i += 1;
                Err(self.err("expected value"))
            }
        }
    }
    fn ident(&mut self, rest: &[u8]) -> Result<(), ParseError> {
        for &c in rest {
            match self.peek() {
                None => return Err(self.err("EOF while parsing a value")),
                Some(b) if b == c => self.i += 1,
                Some(_) => {
                    self.i += 1;
                    return Err(self.err("expected ident"));
                }
            }
        }
        Ok(())
    }
    fn parse_number(&mut self) -> Result<Value, ParseError> {
        let start = self.i;
        let neg = self.peek() == Some(b'-');
        if neg {
            self.i += 1;
        }
        match self.peek() {
            Some(b'0') => {
                self.i += 1;
                if let Some(b'0'..=b'9') = self.peek() {
                    self.i += 1;
                    return Err(self.err("invalid number"));
                }
            }
            Some(b'1'..=b'9') => {
                while let Some(b'0'..=b'9') = self.peek() {
                    self.i += 1;
                }
            }
            None => return Err(self.err("EOF while parsing a value")),
            Some(_) => {
                self.i += 1;
                return Err(self.err("invalid number"));
            }
        }
        let mut is_float = false;
        if self.peek() == Some(b'.') {
            is_float = true;
            self.i += 1;
            match self.peek() {
                Some(b'0'..=b'9') => {}
                None => return Err(self.err("EOF while parsing a value")),
                Some(_) => {
                    self.i += 1;
                    return Err(self.err("invalid number"));
                }
            }
            while let Some(b'0'..=b'9') = self.peek() {
                self.i += 1;
            }
        }
        if let Some(b'e') | Some(b'E') = self.peek() {
            is_float = true;
            self.i += 1;
            if let Some(b'+') | Some(b'-') = self.peek() {
                self.i += 1;
            }
            match self.peek() {
                Some(b'0'..=b'9') => {}
                None => return Err(self.err("EOF while parsing a value")),
                Some(_) => {
                    self.i += 1;
                    return Err(self.err("invalid number"));
                }
            }
            while let Some(b'0'..=b'9') = self.peek() {
                self.i += 1;
            }
        }
        let text = std::str::from_utf8(&self.s[start..self.i]).unwrap();
        if !is_float {
            if neg {
                if let Ok(i) = text.parse::<i64>() {
                    if i == 0 {
                        // serde_json reads -0 as a float
                        return Ok(Value::Num(Num::F(-0.0)));
                    }
                    return Ok(Value::Num(Num::I(i)));
                }
            } else if let Ok(u) = text.parse::<u64>() {
                return Ok(Value::Num(Num::U(u)));
            }
        }
        let f: f64 = text.parse().unwrap_or(f64::INFINITY);
        if !f.is_finite() {
            return Err(self.err("number out of range"));
        }
        Ok(Value::Num(Num::F(f)))
    }
    fn hex4(&mut self) -> Result<u16, ParseError> {
        let mut v: u16 = 0;
        for _ in 0..4 {
            let b = match self.peek() {
                None => return Err(self.err("EOF while parsing a string")),
                Some(b) => b,
            };
            self.i += 1;
            let d = match b {
                b'0'..=b'9' => b - b'0',
                b'a'..=b'f' => b - b'a' + 10,
                b'A'..=b'F' => b - b'A' + 10,
                _ => return Err(self.err("invalid escape")),
            };
            v = v * 16 + d as u16;
        }
        Ok(v)
    }
    fn parse_string(&mut self) -> Result<String, ParseError> {
        let mut out: Vec<u8> = Vec::new();
        loop {
            let b = match self.peek() {
                None => return Err(self.err("EOF while parsing a string")),
                Some(b) => b,
            };
            self.i += 1;
            match b {
                b'"' => break,
                b'\\' => {
                    let e = match self.peek() {
                        None => return Err(self.err("EOF while parsing a string")),
                        Some(e) => e,
                    };
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let c = self.hex4()?;
                            let ch = if (0xD800..0xDC00).contains(&c) {
                                if self.peek() != Some(b'\\') {
                                    return Err(self.err("lone leading surrogate in hex escape"));
                                }
                                self.i += 1;
                                if self.peek() != Some(b'u') {
                                    self.i += 1;
                                    return Err(self.err("unexpected end of hex escape"));
                                }
                                self.i += 1;
                                let c2 = self.hex4()?;
                                if !(0xDC00..0xE000).contains(&c2) {
                                    return Err(self.err("lone leading surrogate in hex escape"));
                                }
                                let n = 0x10000 + (((c as u32) - 0xD800) << 10) + ((c2 as u32) - 0xDC00);
                                char::from_u32(n).unwrap()
                            } else if (0xDC00..0xE000).contains(&c) {
                                return Err(self.err("lone leading surrogate in hex escape"));
                            } else {
                                char::from_u32(c as u32).unwrap()
                            };
                            let mut buf = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                        _ => return Err(self.err("invalid escape")),
                    }
                }
                b if b < 0x20 => {
                    return Err(self.err("control character (\\u0000-\\u001F) found while parsing a string"))
                }
                b => out.push(b),
            }
        }
        match String::from_utf8(out) {
            Ok(s) => Ok(s),
            Err(_) => Err(self.err("invalid unicode code point")),
        }
    }
}

/// Parses a whole JSON text.
pub fn parse(text: &str) -> Result<Value, ParseError> {
    parse_bytes(text.as_bytes())
}

pub fn parse_bytes(bytes: &[u8]) -> Result<Value, ParseError> {
    let mut p = Parser { s: bytes, i: 0, depth: 0 };
    let v = p.parse_value()?;
    p.skip_ws();
    if p.i < p.s.len() {
        p.i += 1;
        return Err(p.err("trailing characters"));
    }
    Ok(v)
}

/// Parses the first JSON value of a text and says where it ended (for `id {json} rest`).
pub fn parse_prefix(text: &str) -> Result<(Value, usize), ParseError> {
    let mut p = Parser { s: text.as_bytes(), i: 0, depth: 0 };
    let v = p.parse_value()?;
    Ok((v, p.i))
}

