                            }
                            16 => {
                                if i == 0 {
                                    return Err(InflateError::Corrupt);
                                }
                                let prev = lens[i - 1];
                                let r = 3 + b.get(2)? as usize;
                                if i + r > lens.len() {
                                    return Err(InflateError::Corrupt);
                                }
                                for _ in 0..r {
                                    lens[i] = prev;
                                    i += 1;
                                }
                            }
                            17 | 18 => {
