level {"elevation": 8000}
' > /tmp/s4.txt; /workspace/executable run --script /tmp/s4.txt; echo "exit=$?"; /workspace/executable run --cmd $'level {"elevation": 6000}
level {}'; echo "exit=$?"; /workspace/executable run --cmd 'level {"elevation": 6000}' --script /tmp/s4.txt; echo "exit=$?"; printf 'level {"elevation": 6000}
level {"elevation": 7000}
' > /tmp/s5.txt; /workspace/executable run --script /tmp/s5.txt --cmd 'level {}'; echo "exit=$?"

python3 - <<'EOF'
p='/workspace/src/main.rs'
s=open(p).read()
old='''    for l in lines {
        match s.execute(&l.id, &l.params) {
            Ok(v) => println!("{}", v.sorted().to_compact()),
            Err(e) => {
                eprintln!("line {} ({}): {}", l.line, l.id, e);
                exit(1);
            }
        }
    }'''
new='''    // a script's replies are printed once all of it has gone through
    let mut out = String::new();
    for l in lines {
        match s.execute(&l.id, &l.params) {
            Ok(v) => {
                out.push_str(&v.sorted().to_compact());
                out.push('\\n');
            }
            Err(e) => {
                eprintln!("line {} ({}): {}", l.line, l.id, e);
                exit(1);
            }
        }
    }
    print!("{}", out);'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
cargo build --release 2>&1 | grep -E "^error" -A 7 | head; cd /tmp && python3 /tmp/tools/cmp.py -q -- run --script /tmp/s4.txt | tail -1; python3 /tmp/tools/cmp.py -q -- run --cmd 'level {"elevation": 6000}' --script /tmp/s4.txt | tail -1

