cd /workspace && mkdir -p src/arch src/structure src/views src/edit src/readers && for m in arch structure views edit readers; do case $m in
arch) doc="Architecture: walls, doors, windows, floors, ceilings, shafts, roofs, dormers, rooms, room separators, stairs, ramps, railings, masses and what is made from them; sketches and shapes.";;
structure) doc="Structure, MEP and families: columns, footings, beams, runs (pipes, ducts, conduits, trays, wires, conductors, cabling), rebar and reinforce, types, families and components, and the sizing calculators.";;
views) doc="Views and annotation: sections, elevations, sheets, viewports, view settings and graphics, filters, templates, 3D views and cameras; text, dimensions, tags, spots, detail lines, regions and groups.";;
edit) doc="Editing: modify, move, copy, rotate, mirror, corner, split, flip, align, delete, insert, link, purge and the like.";;
readers) doc="Reading the model: inspect, elements, schedules, measure, select_by_id, ids_of, filter_selection; reading project files.";;
esac
cat > src/$m/mod.rs <<EOF
//! $doc

use crate::json::Value;
use crate::session::Session;

/// Runs the commands this module owns; None for the others.
pub fn dispatch(s: &mut Session, cid: &str, p: &Value) -> Option<Result<Value, String>> {
    let _ = (s, cid, p);
    None
}

/// The model rules this module owns, checked after every command.
pub fn check(pr: &crate::project::Project) -> Result<(), String> {
    let _ = pr;
    Ok(())
}
EOF
done
cat > src/ifc/import.rs <<'EOF'
//! Reading IFC2x3 and IFC4 files into a project.

use crate::json::Value;
use crate::session::Session;

/// Imports an IFC file as a new project into the session (what `run x.ifc`, `convert` and
/// `open` do); returns the reply `run` prints. An error is what follows `open: `.
pub fn import(s: &mut Session, path: &str) -> Result<Value, String> {
    let _ = s;
    Err(format!("{}: IFC import is not available", path))
}
EOF
